class Solution {
public:
    string getHappyString(int n, int k) {
        int total = 3;
        for (int i = 1; i < n; i++) total *= 2;
        if (k > total) return "";

        string result;
        int groupSize = 1;
        for (int i = 1; i < n; i++) groupSize *= 2;

        char chars[3] = {'a', 'b', 'c'};

        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 3; c++) {
                if (i > 0 && chars[c] == result.back()) continue;
                if (k > groupSize) {
                    k -= groupSize;
                } else {
                    result += chars[c];
                    break;
                }
            }
            groupSize /= 2;
        }
        return result;
    }
};
